public class Main {
    static final int SLOTS = 10;

    static int[] shelf = new int[SLOTS];
    static int[] used = new int[SLOTS];

    // 编号算门牌号：编号除以 10 的余数
    static int slotOf(int id) {
        return id % SLOTS;
    }

    // 存一只：从算出来的格子开始，有人住了就往后挪一格
    static void put(int id) {
        int slot = slotOf(id);
        while (used[slot] != 0) {
            slot = (slot + 1) % SLOTS;
        }
        shelf[slot] = id;
        used[slot] = 1;
    }

    // 找一只：从算出来的格子开始往后敲，答「比了几次」；一格都没住过就答 0
    static int find(int id) {
        int slot = slotOf(id);
        int tries = 0;
        while (used[slot] != 0) {
            tries++;
            if (shelf[slot] == id) {
                return tries;
            }
            slot = (slot + 1) % SLOTS;
        }
        return 0;
    }

    public static void main(String[] args) {
        put({a});
        put({b});

        int n1 = find({a});
        if (n1 > 0) {
            System.out.println("找 {a}：比了 " + n1 + " 次");
        } else {
            System.out.println("找 {a}：没找到");
        }

        int n2 = find({b});
        if (n2 > 0) {
            System.out.println("找 {b}：比了 " + n2 + " 次");
        } else {
            System.out.println("找 {b}：没找到");
        }
    }
}
